import { useEffect, useState } from 'react';
import { Link } from 'react-router';

export default function ChapterListPage() {
  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);
  const [data2, setData2] = useState<unknown>(null);
  const [loading2, setLoading2] = useState<boolean>(true);
  const [error2, setError2] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    const __url = "/api/curriculum/chapters";
    if (__url.indexOf('__MISSING__') !== -1) { if (!cancelled) setLoading1(false); return () => { cancelled = true; }; }
    fetch(__url, { credentials: 'include' })
      .then((r) => r.ok ? r.json() : Promise.reject(new Error('HTTP ' + r.status)))
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e) => { if (!cancelled) setError1((e as Error).message); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, []);
  useEffect(() => {
    let cancelled = false;
    setLoading2(true);
    setError2(null);
    const __url = "/api/curriculum/chapters";
    if (__url.indexOf('__MISSING__') !== -1) { if (!cancelled) setLoading2(false); return () => { cancelled = true; }; }
    fetch(__url, { credentials: 'include' })
      .then((r) => r.ok ? r.json() : Promise.reject(new Error('HTTP ' + r.status)))
      .then((d) => { if (!cancelled) setData2(d); })
      .catch((e) => { if (!cancelled) setError2((e as Error).message); })
      .finally(() => { if (!cancelled) setLoading2(false); });
    return () => { cancelled = true; };
  }, []);

  return (
    <div className="min-h-screen bg-white" data-testid="chapter-list-page">
      <header className="border-b border-gray-200 p-4">
        <Link to="/" className="text-sm text-gray-500" data-testid="chapter-list-home-link">Home</Link>
        <h1 className="mt-2 text-2xl font-bold" data-testid="chapter-list-heading">Chapter list — subject hero with progress, continue CTA on the first available chapter, and per-chapter status (শেষ / রিটেক প্রয়োজন / শুরু হয়নি / লকড) derived from the quiz-pass chain</h1>
      </header>
      <main className="space-y-4 p-4" data-testid="chapter-list-main">
          <section className="rounded border border-gray-200 p-4" data-testid="chapter-list-ac-1">
            <h2 className="mb-2 text-lg font-semibold">Chapters load with subject hero and overall progress</h2>
            {loading1 && <p data-testid="chapter-list-ac-1-loading">Loading...</p>}
            {error1 && <p data-testid="chapter-list-ac-1-error" className="text-red-600">Unable to load</p>}
            {!loading1 && !error1 && (
              <pre className="overflow-auto text-xs" data-testid="chapter-list-ac-1-detail">{JSON.stringify(data1, null, 2)}</pre>
            )}
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="chapter-list-ac-2">
            <h2 className="mb-2 text-lg font-semibold">Each chapter row renders number, title, duration/quiz meta, status badge and mastery</h2>
            {loading2 && <p data-testid="chapter-list-ac-2-loading">Loading...</p>}
            {error2 && <p data-testid="chapter-list-ac-2-error" className="text-red-600">Unable to load</p>}
            {!loading2 && !error2 && (
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-3" data-testid="chapter-list-ac-2-kpis">
                {Object.entries((data2 && typeof data2 === 'object') ? data2 as Record<string, unknown> : {}).slice(0, 6).map(([key, value]) => (
                  <div key={key} data-testid={`chapter-list-ac-2-kpi-${key}`} className="rounded bg-gray-50 p-3">
                    <p className="text-xs text-gray-500">{key}</p>
                    <p className="text-2xl font-bold">{typeof value === 'number' || typeof value === 'string' ? String(value) : '-'}</p>
                  </div>
                ))}
              </div>
            )}
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="chapter-list-ac-3">
            <h2 className="mb-2 text-lg font-semibold">Completed chapters show the done badge and mastery ১০০%</h2>
            <p className="text-sm text-gray-600">Chapters ১–৩ ('সংখ্যা পদ্ধতি', 'যোগ-বিয়োগ গুণ-ভাগ', 'সংখ্যারেখা') render badge 'শেষ' (ksr-badge is-ok) with check icon and '১০০%' mastery; tapping a done row reopens its lesson</p>
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="chapter-list-ac-4">
            <h2 className="mb-2 text-lg font-semibold">Failed-quiz chapter shows the retake badge and routes to the retake class</h2>
            <p className="text-sm text-gray-600">Chapter 'ভগ্নাংশ চিহ্নিতকরণ' renders badge 'রিটেক প্রয়োজন' (ksr-badge is-warn) with mastery '৬৫%'; tapping that row navigates to the retake class route /retake/:retakeId (fixture /retake/bhagnansho) instead of the lesson</p>
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="chapter-list-ac-5">
            <h2 className="mb-2 text-lg font-semibold">Locked chapters are inert and explain the lock state</h2>
            <p className="text-sm text-gray-600">Chapter ৯ 'জ্যামিতিক আকৃতি' renders as a non-link div (data-id ch-9) with lock icon, muted title (.ch-locked-t), badge 'লকড' and mastery '০%'; it is not tappable and unlock is derived from the preceding chapter's quiz-pass chain</p>
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="chapter-list-ac-6">
            <h2 className="mb-2 text-lg font-semibold">'চালিয়ে যাও' continue CTA lands on the first available chapter's lesson</h2>
            <p className="text-sm text-gray-600">The block CTA 'চালিয়ে যাও' (data-testid chapter-continue, play icon) sits on the first unlocked unfinished chapter and navigates to that chapter's lesson route /learn/:classNo/:subjectSlug/:chapterSlug with no extra API call</p>
          </section>
      </main>
    </div>
  );
}
